<?php
/**
 * Luster Compatibility Bridge
 *
 * Place this file alongside your Enthusiast show_*.php compat wrappers.
 * It auto-detects which listing to serve by reading Enthusiast's $listing
 * variable (the dbtable name set by the fanlisting page's config.php).
 *
 * LUSTER_PATH is the only value you need to set — the absolute server path
 * to your Luster installation root (the folder containing src/, public/, etc).
 *
 * Generated by Luster's admin panel. Do not edit unless you know what you're doing.
 */

if (!defined('LUSTER_PATH')) {
    define('LUSTER_PATH', '%%LUSTER_PATH%%');
}

// Auto-detect listing ID from Enthusiast's $listing variable (dbtable name)
if (!isset($luster_fanlisting_id) || (int) $luster_fanlisting_id === 0) {
    $_lbTable = (string) ($listing ?? '');

    if ($_lbTable !== '' && is_file(LUSTER_PATH . '/bootstrap.php')) {
        defined('LUSTER_BASE') || define('LUSTER_BASE', LUSTER_PATH);

        /** @var \Luster\Core\Application $_lbApp */
        $_lbApp = require LUSTER_PATH . '/bootstrap.php';

        try {
            $_lbDb   = $_lbApp->getDatabase();
            $_lbStmt = $_lbDb->prepare(
                'SELECT listingid FROM `' . $_lbDb->validatePrefix('owned') . '` WHERE dbtable = :tbl LIMIT 1'
            );
            $_lbStmt->execute(['tbl' => $_lbTable]);
            $_lbRow = $_lbStmt->fetch(\PDO::FETCH_ASSOC);

            if ($_lbRow !== false) {
                $luster_fanlisting_id = (int) $_lbRow['listingid'];
            }
        } catch (\Throwable) {
        }

        unset($_lbApp, $_lbDb, $_lbStmt, $_lbRow, $_lbTable);
    }
}

// Manual override fallbacks (when $listing is not available)
if (!isset($luster_fanlisting_id) || (int) $luster_fanlisting_id === 0) {
    $luster_fanlisting_id = (int) ($luster_listing_id ?? $listing_id_number ?? $listing_id ?? 0);
}
